style.css:
@-moz-document domain("roblox.com") {
/* Set the entire background to the specified image */
  body {
    background: url(https://i.pinimg.com/474x/5b/f6/12/5bf612f09cd851bbbffd60d173331019.jpg) no-repeat center center fixed;
    background-size: cover;
    color: #c10909; /* Default text color */
  }

  /* Style the header */
  header {
    background: url(https://i.pinimg.com/474x/5b/f6/12/5bf612f09cd851bbbffd60d173331019.jpg) no-repeat center center;
    background-size: cover;
    color: #c10909;
  }

  /* Style all buttons */
  button {
    background-color: #c10909 !important;
    color: #ffffff !important; /* Keep button text visible */
    border: 2px solid #fa3030 !important; /* Highlight color */
  }

  button:hover {
    background-color: #fa3030 !important;
  }

  /* Links */
  a {
    color: #c10909 !important;
  }

  a:hover {
    color: #fa3030 !important;
  }

  /* Input fields */
  input, textarea {
    background-color: #fa3030 !important;
    color: #c10909 !important;
    border: 1px solid #c10909 !important;
  }

  /* Other elements */
  .highlight, .selected, .active {
    background-color: #fa3030 !important;
    color: #c10909 !important;
  }
}
